### 4. **Watch: `fields` with deep watching (Lines 357-375)**
```javascript
fields: {
  deep: true,
  handler(newFields) {
    const groupedFields = {};

    newFields.forEach(field => {
      if (field.fileId !== undefined && field.fileId !== null) {
        if (!groupedFields[field.fileId]) {
          groupedFields[field.fileId] = [];
        }
        groupedFields[field.fileId].push(field);
      }
