- Groups fields by document ID
- Emits `update-fields` event to parent for each document

### 5. **loadPDFs() Method (Lines 385-421)**
```javascript
async loadPDFs(files) {
  this.loadingPDFs = true;
  this.pdfs = [];
  this.pdfPages = {};
  this.scales = {};
  this.signatureCounters = {};  // Line 390: RESETS counter for all docs

  for await (const [index, file] of files.entries()) {
    try {
      // ... PDF loading logic ...
      this.pdfPages[index] = Array.from({ length: pdf.numPages }, (_, i) => i + 1);
      this.currentPage[index] = 1;
      this.signatureCounters[index] = 1;  // Line 408: Initialize counter to 1

      if (index === this.currentDocumentIndex) {
        this.$nextTick(() => {
          this.renderPage(index, this.currentPage[index]);
        });
